<?php
/** Server-side risk indicators, explicitly not browser-measured TBT. @package NakhostinPerformanceEngine */
namespace Nakhostin\PerformanceEngine\Diagnostics;
final class LongMainThreadRiskAnalyzer { public function analyze( array $manifest ): array { $scripts = $manifest['javascript']['assets'] ?? $manifest['javascript'] ?? array(); $styles = $manifest['css']['stylesheets'] ?? array(); $dom = $manifest['dom_complexity'] ?? array(); $bytes = 0; foreach ( is_array( $scripts ) ? $scripts : array() as $script ) { $bytes += is_array( $script ) ? (int) ( $script['bytes'] ?? 0 ) : 0; } return array( 'label' => 'diagnostic_indicator_not_browser_tbt', 'script_count' => count( is_array( $scripts ) ? $scripts : array() ), 'script_bytes_estimate' => $bytes, 'stylesheet_count' => count( is_array( $styles ) ? $styles : array() ), 'css_rule_count' => (int) ( $manifest['css']['rule_count'] ?? 0 ), 'dom_nodes' => (int) ( $dom['nodes'] ?? 0 ), 'dynamic_component_count' => count( $manifest['components'] ?? array() ), 'large_bundle_risk' => $bytes > 500000 ); } }
